function onCreatePost() makeLuaText("fps", "", 0, 0, 1) setTextSize("fps", 16) setObjectCamera("fps", 'other') setTextColor('fps', 'ffffff') addLuaText("fps",true) setTextFont('fps','pixel.ttf') setTextBorder('fps', 0, '000000')  makeLuaText("MemoryCounter", "0 MB", 0, 0, 18) setTextSize("MemoryCounter", 17) setObjectCamera("MemoryCounter", 'other') setTextColor('MemoryCounter', 'ffffff') addLuaText("MemoryCounter",true) setTextFont('MemoryCounter','pixel.ttf') setTextBorder('MemoryCounter', 0, '000000') setObjectOrder('MemoryCounter', 114514) setObjectOrder('fps', 114513) addHaxeLibrary('Main') runHaxeCode([[ Main.fpsVar.visible = false ]]) end  memoryMegasPeak = 0  function onUpdate() local curFps = ""..getPropertyFromClass("Main", "fpsVar.currentFPS") local memoryMegas = round(getPropertyFromClass("openfl.system.System", "totalMemory") / 1000000, 2) if memoryMegasPeak < memoryMegas then memoryMegasPeak = memoryMegas end if memoryMegas> 1024 then memory = round(memoryMegas / 1024,2) measure = "GB" else memory = memoryMegas measure = "MB" end  if memoryMegasPeak> 1024 then memPeak = round(memoryMegasPeak / 1024,2) measurePeak = "GB" else memPeak = memoryMegasPeak measurePeak = "MB" end setTextString("MemoryCounter", memory.." "..measure.. " / "..memPeak.." "..measurePeak.."") setTextString("fps", curFps..' FPS') if getPropertyFromClass("Main", "fpsVar.currentFPS") <= 20 then setTextColor('fps', 'ff0000') setTextColor('MemoryCounter', 'ff0000') else setTextColor('fps', 'ffffff') setTextColor('MemoryCounter', 'ffffff') end end  function round(x, n) n = math.pow(10, n or 0) x = x * n if x >= 0 then x = math.floor(x + 0.5) else x = math.ceil(x - 0.5) end return x / n end